"use client";

import React, { useState, useMemo } from "react";
import { Calendar, ChevronDown, Info, CheckCircle2, AlertCircle } from "lucide-react";

// Data usually fetched from an API
const LEAVE_BALANCES = [
  { id: "annual", label: "Annual Leave", available: 18 },
  { id: "sick", label: "Sick Leave", available: 12 },
  { id: "casual", label: "Casual Leave", available: 5 },
  { id: "unpaid", label: "Loss of Pay", available: 999 },
];

export default function RequestAbsencePage() {
  const [formData, setFormData] = useState({
    leaveType: "annual",
    startDate: "",
    endDate: "",
    reason: "",
  });

  // WORKDAY LOGIC: Calculate working days (skipping weekends)
  const stats = useMemo(() => {
    if (!formData.startDate || !formData.endDate) return { days: 0, error: null };
    
    const start = new Date(formData.startDate);
    const end = new Date(formData.endDate);
    
    if (end < start) return { days: 0, error: "End date is before start date" };

    let count = 0;
    let current = new Date(start);
    while (current <= end) {
      const day = current.getDay();
      if (day !== 0 && day !== 6) count++; // Skip Sat/Sun
      current.setDate(current.getDate() + 1);
    }

    const balance = LEAVE_BALANCES.find(b => b.id === formData.leaveType)?.available || 0;
    return { 
      days: count, 
      error: count > balance ? "Requested days exceed balance" : null 
    };
  }, [formData]);

  return (
    <div className="mx-auto max-w-[1000px] p-6 lg:p-12 font-sans">
      <div className="mb-10">
        <h1 className="text-2xl font-semibold text-gray-900">Request Time Off</h1>
        <p className="text-sm text-gray-500">Submit a new request for approval</p>
      </div>

      <div className="grid grid-cols-1 gap-12 lg:grid-cols-3">
        {/* Main Form Area */}
        <div className="lg:col-span-2 space-y-8">
          <div className="space-y-6 rounded-xl border border-gray-200 bg-white p-8 shadow-sm">
            
            {/* Leave Type Dropdown */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Type of Absence</label>
              <div className="relative">
                <select
                  name="leaveType"
                  value={formData.leaveType}
                  onChange={(e) => setFormData({...formData, leaveType: e.target.value})}
                  className="w-full appearance-none rounded-lg border border-gray-300 px-4 py-3 text-sm focus:border-blue-500 focus:ring-1 focus:ring-blue-500 outline-none transition"
                >
                  {LEAVE_BALANCES.map(b => (
                    <option key={b.id} value={b.id}>{b.label}</option>
                  ))}
                </select>
                <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400 pointer-events-none" />
              </div>
            </div>

            {/* Dates */}
            <div className="grid grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700">Start Date</label>
                <input 
                  type="date" 
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 text-sm outline-none focus:border-blue-500"
                  onChange={(e) => setFormData({...formData, startDate: e.target.value})}
                />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-medium text-gray-700">End Date</label>
                <input 
                  type="date" 
                  min={formData.startDate}
                  className="w-full rounded-lg border border-gray-300 px-4 py-3 text-sm outline-none focus:border-blue-500"
                  onChange={(e) => setFormData({...formData, endDate: e.target.value})}
                />
              </div>
            </div>

            {/* Reason */}
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">Reason</label>
              <textarea 
                rows={3}
                placeholder="Brief details for your manager..."
                className="w-full rounded-lg border border-gray-300 px-4 py-3 text-sm outline-none focus:border-blue-500"
                onChange={(e) => setFormData({...formData, reason: e.target.value})}
              />
            </div>
          </div>

          <div className="flex justify-end gap-4">
            <button className="px-6 py-2.5 text-sm font-medium text-gray-600 hover:bg-gray-50 rounded-lg">Cancel</button>
            <button 
              disabled={!!stats.error || !formData.startDate}
              className="rounded-lg bg-blue-600 px-8 py-2.5 text-sm font-semibold text-white hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-md"
            >
              Submit Request
            </button>
          </div>
        </div>

        {/* Sidebar: Summary & Balance (Workday Style) */}
        <div className="space-y-6">
          <div className="rounded-xl border border-gray-200 bg-white p-6 shadow-sm">
            <h3 className="text-sm font-semibold text-gray-900 mb-4">Balance Details</h3>
            
            <div className="space-y-4">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Available</span>
                <span className="font-bold text-gray-900">
                  {LEAVE_BALANCES.find(b => b.id === formData.leaveType)?.available} Days
                </span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Requested</span>
                <span className="font-bold text-blue-600">{stats.days} Days</span>
              </div>
              <div className="pt-4 border-t border-gray-100 flex justify-between text-sm">
                <span className="font-medium">Remaining</span>
                <span className={`font-bold ${stats.error ? 'text-red-600' : 'text-gray-900'}`}>
                  {(LEAVE_BALANCES.find(b => b.id === formData.leaveType)?.available || 0) - stats.days}
                </span>
              </div>
            </div>

            {/* Error or Success Message */}
            {stats.error ? (
              <div className="mt-6 flex gap-2 rounded-lg bg-red-50 p-3 text-red-700">
                <AlertCircle className="h-4 w-4 shrink-0" />
                <p className="text-xs font-medium">{stats.error}</p>
              </div>
            ) : formData.startDate && (
              <div className="mt-6 flex gap-2 rounded-lg bg-green-50 p-3 text-green-700">
                <CheckCircle2 className="h-4 w-4 shrink-0" />
                <p className="text-xs font-medium">Policy compliant request.</p>
              </div>
            )}
          </div>

          <div className="flex gap-3 p-4 bg-blue-50 rounded-xl">
            <Info className="h-5 w-5 text-blue-500 shrink-0" />
            <p className="text-[11px] text-blue-700 leading-relaxed">
              Weekends (Saturday/Sunday) are automatically excluded from your leave balance calculation.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}